// Package authz holds the explainable authorization decision logic. It is pure
// Go: callers assemble a Data snapshot from storage and receive a stable
// Decision without any database access of their own.
package authz

// Stable reason strings returned in Decision.Reason. They are part of the
// public contract and must not be renamed.
const (
	// ReasonPermissionGranted is the single reason used for every allow result,
	// no matter whether the effective grant is direct, role-based or inherited.
	ReasonPermissionGranted = "permission_granted"
	// ReasonRoleNotMatched means the subject has no usable binding or grant.
	ReasonRoleNotMatched = "role_not_matched"
	// ReasonPermissionNotMatched means a binding/grant exists but none of its
	// permission points covers the requested operation.
	ReasonPermissionNotMatched = "permission_not_matched"
	// ReasonScopeMismatch means an operation-covering permission exists but no
	// copy of it has a scope that covers the requested resource.
	ReasonScopeMismatch = "scope_mismatch"
)

// Scope kinds accepted on stored records.
const (
	ScopeExact  = "exact"
	ScopePrefix = "prefix"
	ScopeAll    = "all"
)

// Input identifies the triple a caller asks about.
type Input struct {
	Subject   string
	Resource  string
	Operation string
}

// Scope is one authorization range boundary.
type Scope struct {
	Kind  string `json:"kind"`
	Value string `json:"value"`
}

// DirectGrant is a permission granted straight to a subject, with its scope.
type DirectGrant struct {
	Permission string
	Scope      Scope
}

// RoleBinding is one role attached to a subject, with its scope.
type RoleBinding struct {
	Role  string
	Scope Scope
}

// RoleParent is one inheritance edge: Role inherits from Parent.
type RoleParent struct {
	Role   string
	Parent string
}

// RolePermission links a role to a permission point it contains.
type RolePermission struct {
	Role       string
	Permission string
}

// PermissionOperation links a permission point to an operation it covers.
type PermissionOperation struct {
	Permission string
	Operation  string
}

// Data is the read-only snapshot the evaluator reasons over.
type Data struct {
	DirectGrants         []DirectGrant
	RoleBindings         []RoleBinding
	RoleParents          []RoleParent
	RolePermissions      []RolePermission
	PermissionOperations []PermissionOperation
}

// Match explains the single effective authorization record.
type Match struct {
	// Via is "direct" for a direct grant and "role" for a role (including an
	// inherited role) binding.
	Via        string `json:"via"`
	Permission string `json:"permission"`
	// Role is the role bound to the subject; empty for direct grants.
	Role  string `json:"role,omitempty"`
	Scope Scope  `json:"scope"`
}

// Decision is the stable result of an evaluation.
type Decision struct {
	Allowed bool   `json:"allowed"`
	Reason  string `json:"reason"`
	Match   *Match `json:"match,omitempty"`
}
package authz

import (
	"sort"
	"strings"
)

// Evaluate answers whether input is allowed using only the given snapshot.
//
// The order of checks is fixed:
//  1. no binding/grant at all -> role_not_matched
//  2. no permission covers the operation -> permission_not_matched
//  3. covering permission exists but no scope covers the resource -> scope_mismatch
//  4. otherwise allowed, explained by the most specific matching record
//
// The result is deterministic for an unchanged snapshot, including ties:
// exact scopes beat prefix scopes beat all scopes, then longer prefixes win,
// then lexicographically smaller scope values, role ids and permission ids.
func Evaluate(input Input, data Data) Decision {
	permCoversOp := indexPermissionOperations(data.PermissionOperations, input.Operation)

	var candidates []candidate
	hasBinding := false

	for _, grant := range data.DirectGrants {
		hasBinding = true
		if !permCoversOp[grant.Permission] {
			continue
		}
		candidates = append(candidates, candidate{
			via:        "direct",
			permission: grant.Permission,
			scope:      grant.Scope,
		})
	}

	reachable := reachableRoles(data.RoleParents)
	roleOwnsPerm := indexRolePermissions(data.RolePermissions)
	for _, binding := range data.RoleBindings {
		hasBinding = true
		roles := reachable[binding.Role]
		if roles == nil {
			roles = []string{binding.Role}
		}
		for _, role := range roles {
			for permission := range roleOwnsPerm[role] {
				if !permCoversOp[permission] {
					continue
				}
				candidates = append(candidates, candidate{
					via:        "role",
					role:       binding.Role,
					permission: permission,
					scope:      binding.Scope,
				})
			}
		}
	}

	if !hasBinding {
		return Decision{Allowed: false, Reason: ReasonRoleNotMatched}
	}
	if len(candidates) == 0 {
		return Decision{Allowed: false, Reason: ReasonPermissionNotMatched}
	}

	matched := make([]candidate, 0, len(candidates))
	for _, item := range candidates {
		if ScopeCovers(item.scope, input.Resource) {
			matched = append(matched, item)
		}
	}
	if len(matched) == 0 {
		return Decision{Allowed: false, Reason: ReasonScopeMismatch}
	}

	sort.SliceStable(matched, func(i, j int) bool {
		return moreSpecific(matched[i], matched[j])
	})
	winner := matched[0]
	return Decision{
		Allowed: true,
		Reason:  ReasonPermissionGranted,
		Match: &Match{
			Via:        winner.via,
			Permission: winner.permission,
			Role:       winner.role,
			Scope:      winner.scope,
		},
	}
}

// candidate is one stored record whose permission covers the requested operation.
type candidate struct {
	via        string
	role       string
	permission string
	scope      Scope
}

// ScopeCovers reports whether scope covers the resource id.
//
// exact  : scope value equals the resource id.
// prefix : scope value is a hierarchy segment ending in "/"; the resource id
//
//	equals the segment without its slash or sits below it. "team-a/" never
//	matches "team-abc", and an empty prefix is rejected.
//
// all    : every resource is covered; scope value must be empty.
func ScopeCovers(scope Scope, resourceID string) bool {
	switch scope.Kind {
	case ScopeExact:
		return scope.Value == resourceID
	case ScopePrefix:
		if scope.Value == "" || !strings.HasSuffix(scope.Value, "/") {
			return false
		}
		base := strings.TrimSuffix(scope.Value, "/")
		return resourceID == base || strings.HasPrefix(resourceID, scope.Value)
	case ScopeAll:
		return scope.Value == ""
	default:
		return false
	}
}

// ValidScope reports whether kind/value form a well-formed stored scope.
func ValidScope(kind, value string) bool {
	switch kind {
	case ScopeExact, ScopePrefix:
		return value != ""
	case ScopeAll:
		return value == ""
	default:
		return false
	}
}

func moreSpecific(a, b candidate) bool {
	if rank := scopeKindRank(a.scope.Kind) - scopeKindRank(b.scope.Kind); rank != 0 {
		return rank < 0
	}
	if len(a.scope.Value) != len(b.scope.Value) {
		return len(a.scope.Value) > len(b.scope.Value)
	}
	if a.scope.Value != b.scope.Value {
		return a.scope.Value < b.scope.Value
	}
	if a.role != b.role {
		return a.role < b.role
	}
	if a.permission != b.permission {
		return a.permission < b.permission
	}
	return a.via < b.via
}

func scopeKindRank(kind string) int {
	switch kind {
	case ScopeExact:
		return 0
	case ScopePrefix:
		return 1
	case ScopeAll:
		return 2
	default:
		return 3
	}
}

func indexPermissionOperations(links []PermissionOperation, operation string) map[string]bool {
	covers := make(map[string]bool)
	for _, link := range links {
		if link.Operation == operation {
			covers[link.Permission] = true
		}
	}
	return covers
}

func indexRolePermissions(links []RolePermission) map[string]map[string]bool {
	owns := make(map[string]map[string]bool)
	for _, link := range links {
		if owns[link.Role] == nil {
			owns[link.Role] = make(map[string]bool)
		}
		owns[link.Role][link.Permission] = true
	}
	return owns
}

// reachableRoles returns, for every role, the role itself followed by every
// role reachable through inheritance. Cycles cannot make the traversal
// infinite thanks to the in-progress memo entry.
func reachableRoles(edges []RoleParent) map[string][]string {
	parents := make(map[string][]string)
	for _, edge := range edges {
		parents[edge.Role] = append(parents[edge.Role], edge.Parent)
	}
	reachable := make(map[string][]string)
	for role := range parents {
		collectRoles(role, parents, reachable)
	}
	return reachable
}

func collectRoles(role string, parents map[string][]string, memo map[string][]string) []string {
	if seen, ok := memo[role]; ok {
		return seen
	}
	memo[role] = []string{} // guard against cycles
	order := []string{role}
	for _, parent := range parents[role] {
		for _, ancestor := range collectRoles(parent, parents, memo) {
			order = appendRoleOnce(order, ancestor)
		}
	}
	memo[role] = order
	return order
}

func appendRoleOnce(order []string, role string) []string {
	for _, existing := range order {
		if existing == role {
			return order
		}
	}
	return append(order, role)
}

