package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// NewRouter wires the public HTTP surface. Health stays at /healthz, the
// recording service lives under /api/v1 and the explainable decision entry is
// GET/POST /api/v1/authorize. Every error keeps the single top-level error
// object described in README.md.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())
	router.HandleMethodNotAllowed = true

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	v1 := router.Group("/api/v1")
	registerAdminRoutes(v1, st)
	v1.GET("/authorize", handleAuthorize(st))
	v1.POST("/authorize", handleAuthorize(st))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	router.NoMethod(func(c *gin.Context) {
		c.JSON(http.StatusMethodNotAllowed, gin.H{"error": gin.H{"code": "method_not_allowed", "message": "this method is not allowed for the path"}})
	})
	return router
}
package api

import (
	"errors"
	"io"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// handleAuthorize is the public explainable decision entry. It never mutates
// records and answers with 200 for every decided outcome (allow or deny); only
// malformed requests, missing inputs or storage faults use error statuses.
func handleAuthorize(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		request, valid := readAuthorizeRequest(c)
		if !valid {
			respondError(c, http.StatusBadRequest, "invalid_request",
				"request must describe one subject, resource and operation")
			return
		}

		subjectExists, resourceExists, operationExists, ok := ensureReferenced(c, st, request)
		if !ok {
			return
		}
		if !subjectExists {
			respondError(c, http.StatusNotFound, "subject_not_found",
				"the subject does not exist")
			return
		}
		if !resourceExists {
			respondError(c, http.StatusNotFound, "resource_not_found",
				"the resource does not exist")
			return
		}
		if !operationExists {
			respondError(c, http.StatusNotFound, "operation_not_found",
				"the operation does not exist")
			return
		}

		data, err := st.DecisionData(request.Subject)
		if err != nil {
			respondStorageError(c)
			return
		}
		decision := authz.Evaluate(authz.Input{
			Subject:   request.Subject,
			Resource:  request.Resource,
			Operation: request.Operation,
		}, data)

		c.JSON(http.StatusOK, gin.H{
			"subject":   request.Subject,
			"resource":  request.Resource,
			"operation": request.Operation,
			"allowed":   decision.Allowed,
			"reason":    decision.Reason,
			"match":     decision.Match,
		})
	}
}

func readAuthorizeRequest(c *gin.Context) (authorizeRequest, bool) {
	var request authorizeRequest
	switch c.Request.Method {
	case http.MethodGet:
		if c.Request.ContentLength > 0 {
			return request, false
		}
		parsed, err := parseAuthorizeQuery(c.Request.URL.RawQuery)
		if err != nil {
			return request, false
		}
		request = parsed
	case http.MethodPost:
		body, err := io.ReadAll(io.LimitReader(c.Request.Body, maxBodyBytes+1))
		if err != nil {
			return request, false
		}
		if len(body) > maxBodyBytes {
			return request, false
		}
		parsed, err := decodeAuthorizeJSON(body)
		if err != nil {
			return request, false
		}
		request = parsed
	default:
		return request, false
	}
	if !validIdentifier(request.Subject) || !validIdentifier(request.Resource) ||
		!validIdentifier(request.Operation) {
		return authorizeRequest{}, false
	}
	return request, true
}

func drainBody(c *gin.Context) error {
	_, err := io.Copy(io.Discard, c.Request.Body)
	return err
}

// ensureReferenced checks existence in the published order subject, resource,
// operation so an unknown input is never reported as a denial.
func ensureReferenced(c *gin.Context, st *store.Store, request authorizeRequest) (subject, resource, operation bool, ok bool) {
