// operation so an unknown input is never reported as a denial.
func ensureReferenced(c *gin.Context, st *store.Store, request authorizeRequest) (subject, resource, operation bool, ok bool) {
	subject, err := st.Exists(store.KindSubject, request.Subject)
	if err != nil {
		respondStorageError(c)
		return false, false, false, false
	}
	resource, err = st.Exists(store.KindResource, request.Resource)
	if err != nil {
