		if !validIdentifier(input.ID) || !validName(input.Name) {
			respondError(c, http.StatusBadRequest, "invalid_request", "id and name must be valid")
			return
		}
		if err := st.PutEntity(kind, input.ID, input.Name); err != nil {
			mapWriteError(c, err)
			return
		}
