// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"fmt"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db  *sql.DB
	seq int64
	now func() time.Time
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	dsn := path
	if strings.Contains(path, "?") {
		dsn += "&_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)"
	} else {
		dsn += "?_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)"
	}
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	// A single connection keeps the foreign_keys pragma and writes deterministic.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	s := &Store{db: db, now: time.Now}
	if err := s.loadSequence(); err != nil {
		db.Close()
		return nil, fmt.Errorf("load sequence: %w", err)
	}
	return s, nil
}

// SetClock overrides the wall clock writes use to stamp valid intervals. It is
// meant for deterministic storage tests; production code keeps the default.
func (s *Store) SetClock(clock func() time.Time) {
	if clock != nil {
		s.now = clock
	}
}

func (s *Store) nowNanos() int64 { return s.now().UTC().UnixNano() }

// nextSeq hands out a process-wide monotonic write sequence so changes that
// share one effective instant keep a stable, replayable order.
func (s *Store) nextSeq(tx *sql.Tx) (int64, error) {
	s.seq++
	return s.seq, nil
}

func (s *Store) loadSequence() error {
	var maxSeq sql.NullInt64
	for _, table := range []string{"subject_role_intervals", "direct_grant_intervals", "role_permission_intervals"} {
		var value sql.NullInt64
		if err := s.db.QueryRow(`SELECT MAX(seq) FROM ` + table).Scan(&value); err != nil {
			return err
		}
		if value.Valid && value.Int64 > maxSeq.Int64 {
			maxSeq = value
		}
	}
	s.seq = maxSeq.Int64
	return nil
}

