package authz

import (
	"sort"
	"strings"
)

// Input identifies the triple a caller asks about.
type Input struct {
	Subject   string
	Resource  string
	Operation string
}

// versionAt reports whether a half-open interval [from, to) is in force at at.
func activeAt(from int64, hasTo bool, to, at int64) bool {
	if from > at {
		return false
	}
	if hasTo && to <= at {
		return false
	}
	return true
}

// intersect returns the overlap of [aFrom,aTo-open) and [bFrom,bTo-open) plus
// whether they overlap. Open ends are represented by hasTo==false.
func intersect(aFrom int64, aHasTo bool, aTo, bFrom int64, bHasTo bool, bTo int64) (int64, bool, int64, bool) {
	from := aFrom
	if bFrom > from {
		from = bFrom
	}
	if !aHasTo {
		if !bHasTo {
			return from, false, 0, true
		}
		return from, true, bTo, from < bTo
	}
	if !bHasTo {
		return from, true, aTo, from < aTo
	}
	to := aTo
	if bTo < to {
		to = bTo
	}
	return from, true, to, from < to
}

// path is one structurally complete authorization chain that may become
// granted on some time interval.
type path struct {
	role   string
	via    string
	perm   string
	scope  Scope
	from   int64
	to     int64
	hasTo  bool
	reason string
	seq    int64
}

// buildPaths collects, for one subject snapshot and triple, every chain where a
// permission point covers the operation and the scope covers the resource.
func buildPaths(data Data, input Input) []path {
	permCoversOp := indexPermissionOperations(data.PermissionOperations, input.Operation)
	paths := make([]path, 0)

	for _, grant := range data.GrantVersions {
		if !permCoversOp[grant.Permission] {
			continue
		}
		if !ScopeCovers(grant.Scope, input.Resource) {
			continue
		}
		paths = append(paths, path{
			via:    "direct",
			perm:   grant.Permission,
			scope:  grant.Scope,
			from:   grant.From,
			to:     grant.To,
			hasTo:  !grant.HasTo,
			reason: grant.CloseReason,
			seq:    grant.Seq,
		})
	}

	reachable := reachableRoles(data.RoleParents)
	rolePerms := indexRolePermissionVersions(data.RolePermissionVersions)
	for _, binding := range data.RoleVersions {
		if !ScopeCovers(binding.Scope, input.Resource) {
			continue
		}
		roles := reachable[binding.Role]
		if roles == nil {
			roles = []string{binding.Role}
		}
		seen := map[string]bool{}
		for _, role := range roles {
			if seen[role] {
				continue
			}
			seen[role] = true
			for _, authorization := range rolePerms[role] {
				if !permCoversOp[authorization.Permission] {
					continue
				}
				from, hasTo, to, ok := intersect(
					binding.From, binding.HasTo, binding.To,
					authorization.From, authorization.HasTo, authorization.To)
				if !ok {
					continue
				}
				paths = append(paths, path{
					role:   binding.Role,
					via:    "role",
					perm:   authorization.Permission,
					scope:  binding.Scope,
					from:   from,
					to:     to,
					hasTo:  hasTo,
					reason: "",
					seq:    0,
				})
			}
		}
	}
	return paths
}

// EvaluateAt answers whether input is granted at instant at. The check order
// mirrors the three stored layers: subject attachment, permission-point
// authorization, scope coverage; temporal failure is only reported once every
// structural layer matches.
func EvaluateAt(input Input, data Data, at int64) Decision {
