	structuralAny := false
	activeLayerAny := false
	candidates := make([]path, 0)

	consider := func(role, via, permission string, scope Scope,
		from int64, hasTo bool, to int64) {
		if !permCoversOp[permission] {
			return
		}
		structuralAny = true
		if activeAt(from, hasTo, to, at) {
			activeLayerAny = true
			if ScopeCovers(scope, input.Resource) {
				candidates = append(candidates, path{
					role: role, via: via, perm: permission, scope: scope,
				})
			}
		}
	}

