package authz

import "sort"

// EvaluateAt answers whether input is granted at instant at.
//
// The structural layers are inspected before time, in the published order:
//  1. the subject carries no role binding or direct grant at all ->
//     NO_ROLE_BINDING;
//  2. a binding/grant exists but no permission point covers the operation
//     through any layer -> NO_PERMISSION_BINDING;
//  3. an operation-covering permission exists but every copy lives on a scope
//     that does not contain the resource -> OUT_OF_SCOPE;
//  4. every layer matches structurally, yet no copy is in force at the asked
//     instant -> NOT_EFFECTIVE;
//  5. otherwise granted, explained by the most specific effective copy.
func EvaluateAt(input Input, data Data, at int64) Decision {
	permCoversOp := indexPermissionOperations(data.PermissionOperations, input.Operation)

	if len(data.RoleVersions) == 0 && len(data.GrantVersions) == 0 {
		return Decision{Granted: false, Reason: ReasonNoRoleBinding}
	}

	structuralChains := chainsFor(input, data, permCoversOp, false)
	effectiveChains := chainsFor(input, data, permCoversOp, true)

	if len(structuralChains) == 0 {
		if permissionLayerExists(data, permCoversOp) {
			return Decision{Granted: false, Reason: ReasonOutOfScope}
		}
		return Decision{Granted: false, Reason: ReasonNoPermissionBinding}
	}

	active := make([]path, 0, len(effectiveChains))
	for _, chain := range effectiveChains {
		if activeAt(chain.from, chain.hasTo, chain.to, at) {
			active = append(active, chain)
		}
	}
	if len(active) == 0 {
		return Decision{Granted: false, Reason: ReasonNotEffective}
	}

	sort.SliceStable(active, func(i, j int) bool {
		return moreSpecific(active[i], active[j])
	})
	winner := active[0]
	return Decision{
		Granted: true,
		Match: &Match{
			Role:       winner.role,
			Permission: winner.perm,
			Scope:      winner.scope,
		},
	}
}

// permissionLayerExists reports whether any role bound to the subject (through
// inheritance) is ever authorized for an operation-covering permission, or
// the subject directly holds such a permission, ignoring scope and time.
func permissionLayerExists(data Data, permCoversOp map[string]bool) bool {
	for _, grant := range data.GrantVersions {
		if permCoversOp[grant.Permission] {
			return true
		}
	}
	reachable := reachableRoles(data.RoleParents)
	owned := map[string]bool{}
	for _, link := range data.RolePermissionVersions {
		owned[link.Role+"\x00"+link.Permission] = true
	}
	for _, binding := range data.RoleVersions {
		roles := reachable[binding.Role]
		if roles == nil {
			roles = []string{binding.Role}
		}
		for _, role := range roles {
			for permission := range permCoversOp {
				if owned[role+"\x00"+permission] {
					return true
				}
			}
		}
	}
	return false
}

// chainsFor enumerates complete layer chains: scope covers the resource, the
// permission point covers the operation, and (for role chains) the binding and
// the role-permission authorization intervals overlap. When requireScope is
// false the scope check is relaxed so callers can distinguish "no permission"
// from "scope mismatch".
func chainsFor(input Input, data Data, permCoversOp map[string]bool, requireScope bool) []path {
	chains := make([]path, 0)

	for _, grant := range data.GrantVersions {
		if !permCoversOp[grant.Permission] {
			continue
		}
		if requireScope && !ScopeCovers(grant.Scope, input.Resource) {
			continue
		}
		chains = append(chains, path{
			via:    "direct",
			perm:   grant.Permission,
			scope:  grant.Scope,
			from:   grant.From,
			to:     grant.To,
			hasTo:  !grant.HasTo,
			reason: grant.CloseReason,
			seq:    grant.Seq,
		})
	}

	reachable := reachableRoles(data.RoleParents)
	rolePerms := indexRolePermissionVersions(data.RolePermissionVersions)
	for _, binding := range data.RoleVersions {
		if requireScope && !ScopeCovers(binding.Scope, input.Resource) {
			continue
		}
		roles := reachable[binding.Role]
		if roles == nil {
			roles = []string{binding.Role}
		}
		seen := map[string]bool{}
		for _, role := range roles {
			if seen[role] {
				continue
			}
			seen[role] = true
			for _, authorization := range rolePerms[role] {
				if !permCoversOp[authorization.Permission] {
					continue
				}
				from, hasTo, to, overlaps := intersect(
					binding.From, binding.HasTo, binding.To,
					authorization.From, authorization.HasTo, authorization.To)
				if !overlaps {
					continue
				}
				chains = append(chains, path{
					role:   binding.Role,
					via:    "role",
					perm:   authorization.Permission,
					scope:  binding.Scope,
					from:   from,
					to:     to,
					hasTo:  hasTo,
					reason: "",
					seq:    0,
				})
			}
		}
	}
	return chains
}
