// chain is one structurally complete authorization path restricted to one
// overlapping validity interval of the layers that form it.
type chain struct {
	role        string
	via         string
	perm        string
	scope       Scope
	from        int64
	to          int64
	hasTo       bool
	openSeq     int64
	closeSeq    int64
	closeReason string
