			!requireEntity(c, st, store.KindPermission, input.ID) {
			return
		}
		if err := st.AuthorizeRolePermission(roleID, input.ID); err != nil {
			if errors.Is(err, store.ErrAlreadyOpen) {
				c.Status(http.StatusNoContent)
				return
			}
			mapWriteError(c, err)
			return
		}
